/**
 * One scenario per check of booked-after-hours-build-standard, for Roof Desk.
 *
 * Generated by `npx @aipathway/conformance init booked-after-hours-build-standard`,
 * then filled in. The checks themselves are fetched at run time from
 * https://aipathway.com.au/explore-ai/booked-after-hours-build-standard; what is
 * here is the world each check starts in, how the build is driven, and what
 * "held" means. Every `holds` reads the world the runner owns, never the build.
 *
 * The line belongs to a Brisbane roofer. Calls ring at 8:30pm local on a
 * Saturday unless a scenario says otherwise. Caller numbers are from ACMA's
 * fictitious range (0491 570 xxx).
 */

import { RoofWorld } from "./roof-world.mjs";

const A = "+61491570156";
const B = "+61491570157";
const C = "+61491570158";
const MIN = 60 * 1000;

const AREA = ["Ashgrove", "Bardon", "Paddington", "The Gap", "Red Hill"];
const RESOLVES = {
  "fourteen ash grove av ash grove": "14 Ashgrove Avenue, Ashgrove QLD 4060",
  "22 latrobe tce paddo": "22 Latrobe Terrace, Paddington QLD 4064",
  "9 boundary rd bardon": "9 Boundary Road, Bardon QLD 4065",
  "5 kitchener st red hill": "5 Kitchener Street, Red Hill QLD 4059",
  "40 margaret st toowoomba": "40 Margaret Street, Toowoomba City QLD 4350",
};

const world = (opts = {}) => new RoofWorld({ serviceArea: AREA, resolves: RESOLVES, ...opts });

/** Ring the line once and run the build for that call. */
async function ring(w, build, phone, utterances) {
  const id = w.ring(phone, utterances);
  await build(w.ports());
  w.hangUp();
  return id;
}

const LEAK = "Water's pouring through the ceiling in the back bedroom, a sheet's lifted in the storm";
const TILES = "I've got a few cracked tiles over the garage and I'd like someone to have a look";
const REROOF = "Can I get a quote to re-roof the house, it's old tin";
const emergencyCall = [LEAK, "fourteen ash grove av ash grove", "yes", "no thanks"];
const routineCall = [TILES, "9 boundary rd bardon", "yes that's right", "no"];
const quoteCall = [REROOF, "5 kitchener st red hill", "yep", "no"];

const creates = (w) => w.calls.filter((c) => c.port === "write_job" && c.request && !("update" in c.request));
const updates = (w) => w.calls.filter((c) => c.port === "write_job" && c.request && "update" in c.request);
const agentTurns = (w) => w.turns.filter((t) => t.who === "agent");
const idx = (w, pred) => w.calls.findIndex(pred);
const TYPES = new Set(["emergency", "routine", "quote", "unclassified"]);
const REASONS = new Set(["unclassified", "address_unresolved", "out_of_scope_request", "caller_distressed", "price_requested", "complaint", "write_failed"]);
const outcomeOf = (w, callId) => w.logs.get(callId)?.outcome ?? null;

export const scenarios = [
  {
    checkId: "disclosure-first",
    // 1. AI identification and the recording notice before the first question.
    world: () => world(),
    drive: (build, w) => ring(w, build, A, routineCall),
    holds: (w) => {
      const turns = w.turns;
      if (turns.length < 3) return false;
      const first = turns[0];
      const firstCall = w.calls[0];
      const firstQuestion = turns.findIndex((t) => t.who === "agent" && t.text.includes("?"));
      return (
        first.who === "agent" &&
        firstCall?.port === "disclose" &&
        /\bAI\b|artificial intelligence/i.test(first.text) &&
        /record/i.test(first.text) &&
        !first.text.includes("?") &&
        firstQuestion > 0 &&
        turns.slice(0, firstQuestion).every((t) => t.who === "agent")
      );
    },
    describe: (w) => `first turn: ${JSON.stringify(w.turns[0] ?? null)}; first port call ${w.calls[0]?.port ?? "none"}`,
  },
  {
    checkId: "verbatim-capture",
    // 2. The caller's words are recorded before anything classifies them.
    world: () => world(),
    drive: (build, w) => ring(w, build, A, emergencyCall),
    holds: (w) => {
      const v = idx(w, (c) => c.port === "write_log" && c.request?.problem_verbatim === LEAK);
      const classified = idx(w, (c) => (c.port === "write_job" && c.request?.type) || c.port === "escalate");
      return v >= 0 && classified >= 0 && v < classified && creates(w)[0]?.request?.type === "emergency";
    },
    describe: (w) => `port order: ${w.calls.map((c) => c.port).join(" > ")}`,
  },
  {
    checkId: "fixed-taxonomy",
    // 3. Three calls: an active leak, cracked tiles, a re-roof quote.
    world: () => world(),
    drive: async (build, w) => {
      await ring(w, build, A, emergencyCall);
      await ring(w, build, B, routineCall);
      await ring(w, build, C, quoteCall);
    },
    holds: (w) => {
      const cs = creates(w);
      if (cs.length !== 3) return false;
      const byPhone = Object.fromEntries(cs.map((c) => [c.request.phone, c.request.type]));
      const enumOnly = cs.every((c) => TYPES.has(c.request.type) && Object.keys(c.request).every((k) => k === "type" || !/type|class|categor|kind/i.test(k)));
      return enumOnly && byPhone[A] === "emergency" && byPhone[B] === "routine" && byPhone[C] === "quote";
    },
    describe: (w) => `writes: ${JSON.stringify(creates(w).map((c) => c.request))}`,
  },
  {
    checkId: "address-resolved",
    // 4. A suburb said once and unclearly; the resolver's answer is read back and written.
    world: () => world(),
    drive: (build, w) => ring(w, build, A, emergencyCall),
    holds: (w) => {
      const heard = "fourteen ash grove av ash grove";
      const resolved = RESOLVES[heard];
      const r = idx(w, (c) => c.port === "resolve_address" && c.request?.spoken === heard && c.response?.resolved === resolved);
      if (r < 0) return false;
      const readBack = w.calls.slice(r + 1).find((c) => c.port === "talk" && typeof c.request?.text === "string" && c.request.text.includes(resolved));
      const echoed = w.calls.some((c) => c.port === "talk" && typeof c.request?.text === "string" && c.request.text.includes(heard));
      const written = creates(w);
      return Boolean(readBack) && !echoed && written.length === 1 && written[0].request.address === resolved && idx(w, (c) => c === written[0]) > r;
    },
    describe: (w) => `resolve: ${JSON.stringify(w.calls.find((c) => c.port === "resolve_address")?.response ?? null)}; written address: ${creates(w)[0]?.request?.address ?? "none"}`,
  },
  {
    checkId: "service-area",
    // 5. An address that resolves outside the service area: told so, no job.
    world: () => world(),
    drive: (build, w) => ring(w, build, A, [TILES, "40 margaret st toowoomba", "yes", "no"]),
    holds: (w) => {
      const r = idx(w, (c) => c.port === "resolve_address" && c.response?.inArea === false);
      if (r < 0) return false;
      const told = w.calls.slice(r + 1).some((c) => c.port === "talk" && /outside the area|don'?t cover|do not cover/i.test(c.request?.text ?? ""));
      const jobWrites = w.calls.filter((c) => c.port === "write_job").length;
      return told && jobWrites === 0 && w.jobs.length === 0;
    },
    describe: (w) => `${w.calls.filter((c) => c.port === "write_job").length} job write(s); last agent turn: ${agentTurns(w).at(-1)?.text ?? "none"}`,
  },
  {
    checkId: "idempotent-write",
    // 6. Same number, same problem, six minutes apart.
    world: () => world(),
    drive: async (build, w) => {
      await ring(w, build, A, emergencyCall);
      w.advance(6 * MIN);
      await ring(w, build, A, emergencyCall);
    },
    holds: (w) => {
      const cs = creates(w);
      const us = updates(w);
      if (w.jobs.length !== 1 || cs.length !== 1 || us.length !== 1) return false;
      const first = cs[0].response?.id;
      const second = outcomeOf(w, "CALL-2");
      return Boolean(first) && us[0].request.update === first && idx(w, (c) => c === us[0]) > idx(w, (c) => c === cs[0]) && second?.job?.duplicate_of === first;
    },
    describe: (w) => `${w.jobs.length} job(s); creates ${creates(w).length}, updates ${updates(w).length}; second call duplicate_of ${outcomeOf(w, "CALL-2")?.job?.duplicate_of ?? "none"}`,
  },
  {
    checkId: "write-verified",
    // 7. The job write comes back with no id.
    world: () => world({ failNextWrite: true }),
    drive: (build, w) => ring(w, build, A, emergencyCall),
    holds: (w) => {
      const failed = idx(w, (c) => c.port === "write_job" && c.response?.id === null);
      if (failed < 0) return false;
      const alerted = w.calls.slice(failed + 1).some((c) => c.port === "notify" && c.request?.reason === "write_failed");
      const out = outcomeOf(w, "CALL-1");
      const claimedBooked = agentTurns(w).some((t) => /booked|reference/i.test(t.text) && !/haven'?t booked/i.test(t.text));
      return alerted && out !== null && out.outcome !== "booked" && out.job.external_id === null && !claimedBooked;
    },
    describe: (w) => `outcome ${JSON.stringify(outcomeOf(w, "CALL-1")?.outcome ?? null)}; notifies ${JSON.stringify(w.alerts)}`,
  },
  {
    checkId: "on-call-discipline",
    // 8. An emergency, a repeat call on the same job, then a routine call.
    world: () => world(),
    drive: async (build, w) => {
      await ring(w, build, A, emergencyCall);
      w.advance(5 * MIN);
      await ring(w, build, A, emergencyCall);
      w.advance(20 * MIN);
      await ring(w, build, B, routineCall);
    },
    holds: (w) => {
      const notes = w.calls.filter((c) => c.port === "notify");
      const emergencyJob = creates(w).find((c) => c.request.phone === A)?.response?.id;
      const routineJob = creates(w).find((c) => c.request.phone === B)?.response?.id;
      return (
        w.jobs.length === 2 &&
        Boolean(emergencyJob) && Boolean(routineJob) &&
        updates(w).length === 1 &&
        notes.length === 1 &&
        notes[0].request.jobId === emergencyJob &&
        notes[0].request.reason === "emergency" &&
        notes[0].callId === "CALL-1"
      );
    },
    describe: (w) => `notifies: ${JSON.stringify(w.calls.filter((c) => c.port === "notify").map((c) => [c.callId, c.request]))}`,
  },
  {
    checkId: "escalation-typed",
    // 9. The caller asks what the job will cost.
    world: () => world(),
    drive: (build, w) => ring(w, build, A, ["How much will it cost to fix a few cracked tiles?", "9 boundary rd bardon", "yes", "no"]),
    holds: (w) => {
      const esc = w.calls.filter((c) => c.port === "escalate");
      if (esc.length !== 1) return false;
      const { reason, transcript } = esc[0].request ?? {};
      const hasWords = Array.isArray(transcript) && transcript.some((t) => t.who === "caller" && /how much/i.test(t.text));
      const priced = agentTurns(w).some((t) => /\$\s?\d|\d+\s?(dollars|bucks)|per (hour|metre|square)/i.test(t.text));
      return REASONS.has(reason) && reason === "price_requested" && hasWords && !priced && w.jobs.length === 0;
    },
    describe: (w) => `escalations: ${JSON.stringify(w.calls.filter((c) => c.port === "escalate").map((c) => c.request?.reason))}; agent: ${agentTurns(w).map((t) => t.text).join(" | ")}`,
  },
  {
    checkId: "consent-before-sms",
    // 10. One caller says yes to a text, one says no.
    world: () => world(),
    drive: async (build, w) => {
      await ring(w, build, A, [TILES, "9 boundary rd bardon", "yes", "yes please"]);
      w.advance(10 * MIN);
      await ring(w, build, B, [REROOF, "5 kitchener st red hill", "yes", "no thanks"]);
    },
    holds: (w) => {
      const sends = w.calls.filter((c) => c.port === "send_sms");
      if (sends.length !== 1 || sends[0].request.to !== A || sends[0].callId !== "CALL-1") return false;
      const s = idx(w, (c) => c === sends[0]);
      const consent = w.calls.slice(0, s).find((c) => c.port === "record_consent" && c.callId === "CALL-1" && c.request?.given === true);
      const refused = w.calls.find((c) => c.port === "record_consent" && c.callId === "CALL-2" && c.request?.given === false);
      return Boolean(consent) && typeof consent.response?.at === "string" && !Number.isNaN(Date.parse(consent.response.at)) && Boolean(refused);
    },
    describe: (w) => `sms: ${JSON.stringify(w.sms)}; consents: ${JSON.stringify(w.consents)}`,
  },
  {
    checkId: "log-survives",
    // 11. A completed call, then a retrieval by call_id.
    world: () => world(),
    drive: async (build, w) => {
      await ring(w, build, A, routineCall);
      await ring(w, build, B, quoteCall);
    },
    holds: (w) => {
      const got = w.retrieve("CALL-1");
      if (!got || !got.outcome || !Array.isArray(got.transcript) || got.calls.length === 0) return false;
      const ports = got.calls.map((c) => c.port);
      const ordered = got.calls.every((c, i, a) => i === 0 || Date.parse(c.at) >= Date.parse(a[i - 1].at));
      const job = got.calls.find((c) => c.port === "write_job")?.response?.id;
      return (
        got.outcome.call_id === "CALL-1" &&
        got.outcome.outcome === "booked" &&
        Boolean(job) && got.outcome.job.external_id === job &&
        got.transcript.some((t) => t.who === "caller" && t.text === TILES) &&
        ports[0] === "disclose" && ports.includes("write_job") &&
        got.calls.every((c) => c.callId === "CALL-1") &&
        ordered
      );
    },
    describe: (w) => {
      const got = w.retrieve("CALL-1");
      return got ? `outcome ${got.outcome?.outcome}; ${got.calls.length} port calls; transcript ${got.transcript?.length ?? 0} turns` : "nothing logged for CALL-1";
    },
  },
];

// The check a stub cannot pass, and is not asked to. It runs only in
// production, on the hosted provider's live line; run.mjs swaps the world.
export const liveScenarios = [
  {
    checkId: "pass-test",
    // 12. Two real calls from one number, then the price question.
    world: () => world(),
    drive: async (build, w) => {
      await build(w.ports());
      await build(w.ports());
    },
    holds: (w) => {
      const calls = w.calls ?? [];
      const jobCreates = calls.filter((c) => c.port === "write_job" && c.request && !("update" in c.request));
      const notifies = calls.filter((c) => c.port === "notify" && c.request?.reason === "emergency");
      const priceHandoff = calls.some((c) => c.port === "escalate" && c.request?.reason === "price_requested");
      return calls[0]?.port === "disclose" && jobCreates.length === 1 && jobCreates[0].request?.type === "emergency" && notifies.length === 1 && priceHandoff;
    },
    describe: (w) => `${(w.calls ?? []).length} port call(s)`,
  },
];
